# Download sanjo kouki PDFs from R2
for yr in 2023 2024 2025; do
  for ct in problem answer; do
    node -e "
      const { S3Client, GetObjectCommand } = require(\"@aws-sdk/client-s3\");
      const fs = require(\"fs\");
      const s3 = new S3Client({
        region: \"auto\",
        endpoint: \"https://\" + process.env.R2_ACCOUNT_ID + \".r2.cloudflarestorage.com\",
        credentials: { accessKeyId: process.env.R2_ACCESS_KEY_ID, secretAccessKey: process.env.R2_SECRET_ACCESS_KEY }
      });
      (async () => {
        const res = await s3.send(new GetObjectCommand({ Bucket: process.env.R2_BUCKET_NAME, Key: \"sanjo/${yr}/math/kouki/${ct}.pdf\" }));
        const buf = Buffer.from(await res.Body.transformToByteArray());
        fs.writeFileSync(\"/tmp/verify-chubu/sanjo_${yr}_kouki_${ct}.pdf\", buf);
        console.log(\"sanjo ${yr} kouki ${ct}: \" + buf.length + \" bytes\");
      })();
    "
  done
done
' 2>/dev/null

./scripts/with-env.sh bash -c '
# Download pu_toyama nursing answer and fukui med from R2
for item in "pu_toyama/2025/math_nursing/zenki/answer.pdf:pu_toyama_nursing_answer" "fukui/2025/math_med/zenki/problem.pdf:fukui_med_problem" "fukui/2025/math_med/zenki/answer.pdf:fukui_med_answer"; do
  key="${item%%:*}"
  name="${item##*:}"
  node -e "
    const { S3Client, GetObjectCommand } = require(\"@aws-sdk/client-s3\");
    const fs = require(\"fs\");
    const s3 = new S3Client({
      region: \"auto\",
      endpoint: \"https://\" + process.env.R2_ACCOUNT_ID + \".r2.cloudflarestorage.com\",
      credentials: { accessKeyId: process.env.R2_ACCESS_KEY_ID, secretAccessKey: process.env.R2_SECRET_ACCESS_KEY }
    });
    (async () => {
      const res = await s3.send(new GetObjectCommand({ Bucket: process.env.R2_BUCKET_NAME, Key: \"${key}\" }));
      const buf = Buffer.from(await res.Body.transformToByteArray());
      fs.writeFileSync(\"/tmp/verify-chubu/${name}.pdf\", buf);
      console.log(\"${name}: \" + buf.length + \" bytes\");
    })();
  "
done
' 2>/dev/null

# Check if fukui med and ms are the same PDF
./scripts/with-env.sh bash -c '
for variant in med ms; do
  for ct in problem answer; do
    node -e "
      const { S3Client, GetObjectCommand } = require(\"@aws-sdk/client-s3\");
      const fs = require(\"fs\");
      const crypto = require(\"crypto\");
      const s3 = new S3Client({
        region: \"auto\",
        endpoint: \"https://\" + process.env.R2_ACCOUNT_ID + \".r2.cloudflarestorage.com\",
        credentials: { accessKeyId: process.env.R2_ACCESS_KEY_ID, secretAccessKey: process.env.R2_SECRET_ACCESS_KEY }
      });
      (async () => {
        const res = await s3.send(new GetObjectCommand({ Bucket: process.env.R2_BUCKET_NAME, Key: \"fukui/2025/math_${variant}/zenki/${ct}.pdf\" }));
        const buf = Buffer.from(await res.Body.transformToByteArray());
        const hash = crypto.createHash(\"md5\").update(buf).digest(\"hex\");
        console.log(hash + \"  fukui_${variant}_${ct} (\" + buf.length + \" bytes)\");
      })();
    "
  done
done
' 2>/dev/null

