#!/usr/bin/env tsx
/**
 * Download files from R2 to local disk.
 *
 * Usage:
 *   npx tsx scripts/download-r2.ts <r2_path> <local_path>
 *   npx tsx scripts/download-r2.ts <r2_path>               # → writes to ./<basename>
 *   npx tsx scripts/download-r2.ts --prefix <r2_prefix> --out-dir <dir>  # bulk download
 *
 * Examples:
 *   npx tsx scripts/download-r2.ts nagoya/2025/math/zenki/problem.pdf /tmp/verify/nagoya_p.pdf
 *   npx tsx scripts/download-r2.ts --prefix nagoya/2025/math --out-dir /tmp/verify
 */

import { S3Client, GetObjectCommand, ListObjectsV2Command } from "@aws-sdk/client-s3";
import * as fs from "fs";
import * as path from "path";

function getArg(name: string): string | null {
  const idx = process.argv.indexOf(name);
  if (idx >= 0 && process.argv[idx + 1]) return process.argv[idx + 1];
  return null;
}

const accountId = process.env.R2_ACCOUNT_ID;
const accessKeyId = process.env.R2_ACCESS_KEY_ID;
const secretAccessKey = process.env.R2_SECRET_ACCESS_KEY;
const bucketName = process.env.R2_BUCKET_NAME ?? "kakomon";

if (!accountId || !accessKeyId || !secretAccessKey) {
  console.error("R2_ACCOUNT_ID, R2_ACCESS_KEY_ID, R2_SECRET_ACCESS_KEY are required");
  process.exit(1);
}

const r2 = new S3Client({
  region: "auto",
  endpoint: `https://${accountId}.r2.cloudflarestorage.com`,
  credentials: { accessKeyId, secretAccessKey },
});

async function downloadOne(key: string, localPath: string): Promise<void> {
  const res = await r2.send(new GetObjectCommand({ Bucket: bucketName, Key: key }));
  if (!res.Body) throw new Error(`Empty body for ${key}`);

  fs.mkdirSync(path.dirname(localPath), { recursive: true });
  const stream = fs.createWriteStream(localPath);
  for await (const chunk of res.Body as AsyncIterable<Uint8Array>) {
    stream.write(chunk);
  }
  stream.end();
  await new Promise<void>((resolve, reject) => {
    stream.on("finish", resolve);
    stream.on("error", reject);
  });

  const size = fs.statSync(localPath).size;
  console.log(`OK: ${key} → ${localPath} (${size} bytes)`);
}

async function main() {
  const prefix = getArg("--prefix");
  const outDir = getArg("--out-dir");

  if (prefix) {
    // Bulk mode: list all objects under prefix and download
    const dir = outDir ?? ".";
    const listRes = await r2.send(new ListObjectsV2Command({
      Bucket: bucketName,
      Prefix: prefix,
    }));

    const objects = listRes.Contents ?? [];
    if (objects.length === 0) {
      console.error(`No objects found under prefix: ${prefix}`);
      process.exit(1);
    }

    console.log(`Found ${objects.length} objects under ${prefix}\n`);
    for (const obj of objects) {
      if (!obj.Key) continue;
      // Flatten path: nagoya/2025/math_bun/zenki/problem.pdf → nagoya_2025_math_bun_zenki_problem.pdf
      const flat = obj.Key.replace(/\//g, "_");
      await downloadOne(obj.Key, path.join(dir, flat));
    }
    console.log(`\nDone: ${objects.length} files downloaded to ${dir}`);
  } else {
    // Single file mode
    const positional = process.argv.slice(2).filter(a => !a.startsWith("--"));
    if (positional.length < 1) {
      console.error("Usage:");
      console.error("  npx tsx scripts/download-r2.ts <r2_path> [local_path]");
      console.error("  npx tsx scripts/download-r2.ts --prefix <r2_prefix> --out-dir <dir>");
      process.exit(1);
    }

    const r2Path = positional[0];
    const localPath = positional[1] ?? path.basename(r2Path);
    await downloadOne(r2Path, localPath);
  }
}

main().catch((err) => { console.error(`FAIL: ${err.message}`); process.exit(1); });

